function samplePath(name:string,programId:string,planned:string[],completed:string[]):SavedPath {
  const courses:PlannedCourse[]=[...completed.map(courseId=>({courseId,term:TERMS[0],status:'completed' as const})),...planned.map((courseId,i)=>({courseId,term:TERMS[Math.min(1+Math.floor(i/3),4)],status:'planned' as const}))].filter(c=>courseMap.has(c.courseId));
  return {id:uid(),name,programId,courses,createdAt:now(),updatedAt:now(),catalogYear:catalog.catalogYear};
}
